INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will LeBron James win the 2028 US Presidential Election?', 'The 2028 US Presidential Election is scheduled to take place on November 7, 2028. This market will resolve to the person who wins the 2028 US Presidential Election. The resolution source for this market is the Associated Press, Fox News, and NBC. This market will resolve once all three sources call the race for the same candidate. If all three sources haven’t called the race for the same candidate by the inauguration date (January 20, 2029) this market will resolve based on who is inaugurated.', 'politics', 'active', 272516.71, 26979154.08, 273016.71, 26979654.08);
