INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Strait of Hormuz traffic returns to normal by August 31?', 'This market will resolve to “Yes” if IMF Portwatch publishes a 7-day moving average of transit calls (“Arrivals of Ships”) for the Strait of Hormuz equal to or above 60 for any date between market creation and August 31, 2026. Otherwise, this market will resolve to “No”. Daily transit calls include container, dry bulk, roll-on/roll-off, general cargo, and tanker ships. Ships not reported by IMF Portwatch will not be considered. This market will resolve as soon as IMF Portwatch publishes a 7-day ', 'politics', 'active', 169544.78, 5995719.97, 170044.78, 5996219.97);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Nebius Group be acquired before 2027?', 'This market will resolve to “Yes” if credible reporting confirms that any entity enters into an agreement to acquire the listed company by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No”. Mergers where the listed company is subsumed by another entity will count toward a "Yes" resolution. An announced agreement between the listed company and an acquiring entity will qualify for a “Yes” resolution, regardless of whether the acquisition is ultimately completed. The prima', 'tech', 'active', 254466.8, 3721576.94, 254966.8, 3722076.94);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Hantavirus pandemic in 2026?', 'This market will resolve to "Yes" if the World Health Organization explicitly characterizes Hantavirus, Hantavirus Pulmonary Syndrome (HPS), Hemorrhagic Fever with Renal Syndrome (HFRS), or a Hantavirus-related outbreak as a "pandemic" in an official public communication between market creation and December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". An explicit characterization includes official WHO statements, reports, press briefings, or publications that clearly descr', 'general', 'active', 338330.64, 8565107.36, 338830.64, 8565607.36);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Iran agrees to surrender enriched uranium stockpile by December 31, 2026?', 'This market will resolve to "Yes" if Iran publicly agrees to surrender its enriched uranium stockpile by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No”. An official pledge by Iran to surrender its enriched uranium stockpile will qualify for a “Yes” resolution whether as a unilateral announcement or part of an agreement with the U.S. or Israel. An agreement by Iran to surrender any amount of its enriched uranium stockpile will count. To qualify, Iran must publicly agr', 'politics', 'active', 89875.02, 967478.17, 90375.02, 967978.17);
