INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will María Corina Machado enter Venezuela by August 31?', 'If María Corina Machado visits Venezuela between market creation and August 31, 2026, 11:59 PM ET, this market will resolve to "Yes". Otherwise, this market will resolve to "No". For the purpose of this market, a "visit" is defined as María Corina Machado physically entering the terrestrial territory of Venezuela. Whether or not María Corina Machado enters Venezuelan airspace or maritime territory during the timeframe of this market will have no bearing on a positive resolution. The primary reso', 'politics', 'active', 270.15, 3885.95, 770.15, 4385.95);
