INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Game 2: Any Player Quadra Kill?', 'This market is about whether any player achieves a Quadra Kill during Game 2. In League of Legends, a Quadra Kill occurs when a single player kills 4 enemy champions in rapid succession. This market will resolve to "Yes" if any player on either team achieves a Quadra Kill during Game 2. This market will resolve to "No" if no player achieves a Quadra Kill. A Penta Kill (5 kills in rapid succession) also counts as a Quadra Kill having occurred for the purposes of this market. If the match is cance', 'sports', 'active', 1575304.04, 1575304.04, 1575804.04, 1575804.04);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will US withdraw from NATO before 2027?', 'This market will resolve to "Yes" if the United States formally initiates a withdrawal from NATO or provides an official notice of denunciation to NATO by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". A notice of denunciation refers to the submission of a notice of withdrawal as per Article 13 of the North Atlantic Treaty. Any action meeting these criteria will qualify for a “Yes” resolution regardless of if its implementation is immediately halted or delayed by ju', 'politics', 'active', 21234.32, 622230.06, 21734.32, 622730.06);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Minnesota Vikings win the 2027 NFL NFC Championship?', 'This market will resolve according to the team that wins the 2027 NFC championship game. If at any point it becomes impossible for a listed team to win the 2027 NFL NFC championship per the rules of the NFL (e.g., they are eliminated in the playoffs), the corresponding market will resolve to “No”. If the 2027 NFL NFC championship game is cancelled, postponed after March 31, 2027 ET, or there is otherwise no winner declared within that timeframe, this market will resolve to “Other”. The primary r', 'sports', 'active', 35096.36, 913453.9, 35596.36, 913953.9);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Grigor Dimitrov win the 2026 Men''s US Open?', 'The 2026 U.S. Open tennis tournament is scheduled for August 23 - September 13, 2026. This market will resolve to the player that wins the 2026 U.S. Open Men’s Singles Tournament. If at any point it becomes impossible for a listed player to win the 2026 U.S. Open Men’s Singles Tournament per the rules of the tournament, the corresponding market will resolve to “No”. If the 2026 U.S. Open Men’s Singles Tournament is cancelled, postponed after October 31, 2026, or there is otherwise no winner decl', 'sports', 'active', 3769.02, 373132.88, 4269.02, 373632.88);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Predict.fun FDV above $200M one day after launch?', 'This market will resolve to "Yes" if the Fully Diluted Valuation of Predict.fun''s governance token is greater than the value specified in the title 1 day after launch. Otherwise, the market will resolve to "No." The token must be actively, publicly transferable and tradable to be considered a launch. The FDV will be determined using the total token supply multiplied by the token price. "1 day after launch" is defined as 4:00 PM ET on the calendar day following launch. The resolution source for ', 'crypto', 'active', 409890.18, 140297.98, 410390.18, 140797.98);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Russia test a nuclear weapon by September 30 2026?', 'This market will resolve to "Yes" if Russia conducts a nuclear test by the listed date (ET). Otherwise, this market will resolve to "No". A nuclear test is defined as the intentional non-combat detonation of a device by Russia that produces a nuclear chain reaction (fission or fusion), regardless of yield. Accidents, radiological dispersal devices (bombs that spread radioactive material using conventional explosives such as "dirty bombs"), or actions by third parties will not count toward this m', 'politics', 'active', 941.43, 68793.82, 1441.4299999999998, 69293.82);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Russia x Ukraine ceasefire agreement by December 31, 2026?', 'This market will resolve to “Yes” if there is a ceasefire agreement between Russia and Ukraine by the specified date, 11:59 PM ET. Otherwise, this market will resolve to “No”. A ceasefire agreement refers to any mutually-agreed suspension of direct military engagement between Russia and Ukraine, which is either officially announced by both countries or confirmed by a consensus of credible reporting to have been mutually agreed by both countries. A broader peace deal, normalization agreement, pol', 'politics', 'active', 281128.35, 779733.34, 281628.35, 780233.34);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will NVIDIA be the largest company in the world by market cap on December 31?', 'This market will resolve to the largest company in the world by market cap on December 31, 2026, as of market close. The resolution source for this market will be a consensus of credible reporting.', 'tech', 'active', 356469.71, 149161.09, 356969.71, 149661.09);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will WTI Crude Oil (WTI) hit (HIGH) $85 in August?', 'This market will resolve to "Yes" if, at any point after market creation and during a trading session of August 2026, any 1-minute candle for the Active Month of WTI Crude Oil futures has a final "High" or "Low" price equal to or beyond (above for ↑ High Prices, below for ↓ Low Prices) the listed price. Otherwise, this market will resolve to "No". Prices will be used exactly as published by Pyth, without rounding. If the Active Month contract does not trade at all during the listed time frame, t', 'general', 'active', 222173.37, 60850.03, 222673.37, 61350.03);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Puffpaw FDV above $100M one day after launch?', 'This market will resolve to "Yes" if the Fully Diluted Valuation of Puffpaw''s governance token is greater than the value specified in the title 1 day after launch. Otherwise, the market will resolve to "No." The token must be actively, publicly transferable and tradable to be considered a launch. The FDV will be determined using the total token supply multiplied by the token price. "1 day after launch" is defined as 4:00 PM ET on the calendar day following launch. The resolution source for this', 'crypto', 'active', 169105.25, 676421.02, 169605.25, 676921.02);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Russia invade a NATO country by December 31, 2026?', 'This market will resolve to "Yes" if Russia commences a military offensive intended to establish control over any portion of any NATO country by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". For the purposes of this market, land de facto controlled by NATO member states or Russia as of May 28, 2025, will be considered the sovereign territory of those countries. Hybrid or “grey zone” operations conducted by unmarked personnel will qualify if they are confirmed to be', 'politics', 'active', 6834.78, 117433.87, 7334.78, 117933.87);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Manchester City win the 2026-27 English Premier League (EPL) Championship?', 'This market will resolve according to the team that wins the 2026-27 English Premier League (EPL) Championship. If at any point it becomes impossible for a listed team to win the 2026-27 English Premier League (EPL) Championship per the rules of English Premier League (EPL) (e.g., they are eliminated in the playoffs), the corresponding market will resolve to "No". If the 2026-27 English Premier League (EPL) season is cancelled, postponed after June 14, 2027, 11:59 PM ET or there is otherwise no ', 'sports', 'active', 204647.14, 567606.21, 205147.14, 568106.21);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Anthropic have the highest IPO Market Cap 2026?', 'This market will resolve to the company that achieves the highest market capitalization in U.S. dollars based on the official closing price on its first trading day in 2026. This market will resolve to a company that completes an Initial Public Offering (IPO) between January 1 and December 31, 2026, 11:59 PM ET. Market capitalization is defined as the total number of outstanding shares multiplied by the closing share price on the first trading day. If two or more companies have exactly equal hig', 'tech', 'active', 36911.73, 321454.6, 37411.73, 321954.6);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Tyreek Hill play for the Chicago Bears next?', 'This market will resolve to the next NFL team Tyreek Hill joins by August 31, 2026, 11:59 PM ET. If Tyreek Hill does not join a new NFL team by August 31, 2026, 11:59 PM ET, this market will resolve to “Other”. If Tyreek Hill joins a team that is not listed, this market will resolve to “Other”. If Tyreek Hill is released and is not signed by another team, retires, or is not under contract with any NFL team by August 31, 2026, 11:59 PM ET, this market will resolve to “Other”. Transfers or assignm', 'sports', 'active', 10967.35, 1085767.36, 11467.35, 1086267.36);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Bitcoin reach $100,000 in August?', 'This market will immediately resolve to "Yes" if any Binance 1 minute candle for BTC/USDT during the month specified in the title (from 00:00 AM ET on the first day to 11:59 PM ET on the last), has a final High price equal to or greater than the price specified in the title. Otherwise, this market will resolve to "No." The resolution source for this market is Binance, specifically the BTC/USDT High prices available at https://www.binance.com/en/trade/BTC_USDT, with the chart settings on "1m" for', 'crypto', 'active', 2722.99, 269575.75, 3222.99, 270075.75);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('LoL: Bilibili Gaming vs JD Gaming (BO3) - LPL Group Ascend', 'This market refers to the LoL match between Bilibili Gaming and JD Gaming in the LPL Group Ascend, initially scheduled for August 12 at 7:00AM ET. This market will resolve to "Bilibili Gaming" if Bilibili Gaming win the match against JD Gaming. This market will resolve to "JD Gaming" if JD Gaming win the match against Bilibili Gaming. If the match is canceled (not played at all), ends in a tie, or is delayed beyond 7 days from the scheduled date without a winner determined, this market will reso', 'sports', 'active', 12227.08, 1210481.22, 12727.08, 1210981.22);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Satoshi move any Bitcoin in 2026?', 'This market will resolve to “Yes” if any wallet labeled as belonging to Satoshi Nakamoto on Arkham’s Intel Explorer shows an “Outflow” or “Swaps” transaction at any time between January 9, 2026, 1:00 PM ET and December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No.” The resolution source for this market is Arkham’s Intel Explorer, specifically the entity page for Satoshi Nakamoto available at https://intel.arkm.com/explorer/entity/satoshi-nakamoto If Arkham becomes permanentl', 'crypto', 'active', 109837.55, 2252260.2, 110337.55, 2252760.2);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Count Binface win the Clacton by-election?', 'A by-election for the United Kingdom parliamentary constituency of Clacton is expected to be held soon following the announced resignation of incumbent Nigel Farage. This market will resolve according to the candidate who wins the Clacton parliamentary by-election. If the election results are not known definitively by June 30, 2027, 11:59 PM ET, this market will resolve to "Other". The resolution source for this market will be a consensus of credible reporting. In case of ambiguity, this market ', 'politics', 'active', 15005.25, 1414066.44, 15505.25, 1414566.44);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Renan Santos finish in second place in the first round of the 2026 Brazilian presidential election?', 'A presidential election is scheduled to take place in Brazil on October 4, 2026. This market will resolve according to the listed candidate who receives the second-most valid votes in the first round of this election. The named candidates will be primarily ranked by the number of valid votes received in the specified election. If two or more candidates are tied on valid votes, ties will be broken by alphabetical order of the candidates'' last names. This market will resolve to the candidate that', 'politics', 'active', 47238.22, 502043.43, 47738.22, 502543.43);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Epstein client list released by October 31?', 'This market will resolve to “Yes” if files which were not previously public and which pertain to the illegal activities of Jeffrey Epstein are made public by October 31, 2026, 11:59 PM ET, and those files contain a list of individuals associated with Epstein in connection with his illegal activities, including but not limited to sex trafficking or related crimes. Otherwise, this market will resolve to “No.” To qualify, the files must contain names in a context equivalent to what is commonly refe', 'politics', 'active', 60, 940, 560, 1440);